 3	public final class BubbleSort {
 4	    private static final char VALUE_SEPARATOR = ' ';
 5	
 6	    private BubbleSort() {
 7	        // Utility class.
 8	    }
 9	
10	    public static void sort(int[] values) {
11	        Objects.requireNonNull(values, "values");
12	
13	        if (hasFewerThanTwoValues(values)) {
14	            return;
15	        }
16	
17	        for (int lastUnsortedIndex = values.length - 1; lastUnsortedIndex > 0; lastUnsortedIndex--) {
18	            if (!bubbleLargestValueToEnd(values, lastUnsortedIndex)) {
19	                return;
20	            }
21	        }
22	    }
23	
24	    public static void printArray(int[] values) {
25	        System.out.println(toDisplayString(values));
26	    }
27	
28	    public static String toDisplayString(int[] values) {
29	        Objects.requireNonNull(values, "values");
30	
31	        StringBuilder output = new StringBuilder();
32	
33	        for (int value : values) {
34	            if (!output.isEmpty()) {
35	                output.append(VALUE_SEPARATOR);
36	            }
37	            output.append(value);
38	        }
39	
40	        return output.toString();
41	    }
42	
43	    private static boolean hasFewerThanTwoValues(int[] values) {
44	        return values.length < 2;
45	    }
46	
47	    private static boolean bubbleLargestValueToEnd(int[] values, int lastUnsortedIndex) {
48	        boolean swapped = false;
49	
50	        for (int currentIndex = 0; currentIndex < lastUnsortedIndex; currentIndex++) {
51	            if (values[currentIndex] > values[currentIndex + 1]) {
52	                swap(values, currentIndex, currentIndex + 1);
53	                swapped = true;
54	            }
55	        }
56	
57	        return swapped;
58	    }
59	
60	    private static void swap(int[] values, int leftIndex, int rightIndex) {
61	        int temporary = values[leftIndex];
62	        values[leftIndex] = values[rightIndex];
63	        values[rightIndex] = temporary;
64	    }
65	}

